"use client";

import { getChart } from "@/lib/chart-registry";
import { CHART_TIME_AXIS_H } from "@/lib/drawings";
import { useAppStore } from "@/lib/store";
import type { ChartSettings } from "@/types";
import {
  useEffect,
  useState,
  type CSSProperties,
  type MouseEvent as ReactMouseEvent,
  type RefObject,
} from "react";
import { ChartScaleMenu } from "@/components/charts/ChartScaleMenu";

type Mode = ChartSettings["scaleModes"];

type Props = {
  paneId: string;
  mode: Mode;
  hostRef: RefObject<HTMLElement | null>;
  active: boolean;
  onActiveChange: (active: boolean) => void;
};

const TIME_AXIS_H = CHART_TIME_AXIS_H;
/** Approximate right price-axis width (Vela does not expose a measured width). */
const FALLBACK_AXIS_W = 56;

type CornerBox = { left: number; top: number; width: number; height: number };

export function applyAutoFit(paneId: string) {
  const handle = getChart(paneId);
  if (!handle) return;
  // Price axis only — fit visible candles vertically; leave time zoom/scroll alone.
  try {
    handle.vela.renderer.set("autoScale", true);
  } catch {
    /* renderer may not expose the feature */
  }
}

function rightAxisWidth(_paneId: string) {
  return FALLBACK_AXIS_W;
}

function isAutoScaleOn(paneId: string): boolean {
  const handle = getChart(paneId);
  if (!handle) return true;
  try {
    return handle.vela.renderer.get("autoScale") !== false;
  } catch {
    return true;
  }
}

/**
 * Measure the bottom-right corner of the **main price pane** (pane index 0)
 * so the "auto" label is anchored there — not at the very bottom of the full
 * chart, which sinks below all indicator sub-panes.
 */
function measureAutoCorner(host: HTMLElement, _paneId: string): CornerBox {
  const hostRect = host.getBoundingClientRect();
  const axisW = rightAxisWidth(_paneId);
  // Geometry-based: the price axis column sits at the bottom-right of the host.
  return {
    left: Math.round(hostRect.width - axisW),
    top: Math.round(hostRect.height - TIME_AXIS_H),
    width: axisW,
    height: TIME_AXIS_H,
  };
}


function isOnPriceOrTimeScale(
  host: HTMLElement,
  _paneId: string,
  clientX: number,
  clientY: number,
): boolean {
  const rect = host.getBoundingClientRect();
  const x = clientX - rect.left;
  const y = clientY - rect.top;
  if (x < 0 || y < 0 || x > rect.width || y > rect.height) return false;

  const rightW = FALLBACK_AXIS_W;
  const onRightPrice = x >= rect.width - rightW - 1;
  const onTime = y >= rect.height - TIME_AXIS_H;
  return onRightPrice || onTime;
}

function isInAutoCorner(
  host: HTMLElement,
  paneId: string,
  clientX: number,
  clientY: number,
): boolean {
  const rightW = rightAxisWidth(paneId);
  const rect = host.getBoundingClientRect();
  return clientX >= rect.right - rightW && clientY >= rect.bottom - TIME_AXIS_H;
}


export function clearAutoFit(paneId: string) {
  const handle = getChart(paneId);
  if (!handle) return;
  // The current price window is kept as-is; only auto-fitting is disabled.
  try {
    handle.vela.renderer.set("autoScale", false);
  } catch {
    /* renderer may not expose the feature */
  }
}

export function ChartAutoScale({ paneId, mode, hostRef, active, onActiveChange }: Props) {
  const setActivePane = useAppStore((s) => s.setActivePane);
  const [corner, setCorner] = useState<CornerBox>({
    left: 0,
    top: 0,
    width: FALLBACK_AXIS_W,
    height: TIME_AXIS_H,
  });

  // Track the live scale-corner cell so the label fills and centers in it.
  useEffect(() => {
    if (mode === "never") return;
    const sync = () => {
      const host = hostRef.current;
      if (!host) return;
      const next = measureAutoCorner(host, paneId);
      setCorner((prev) =>
        prev.left === next.left &&
        prev.top === next.top &&
        prev.width === next.width &&
        prev.height === next.height
          ? prev
          : next,
      );
    };
    sync();
    const host = hostRef.current;
    const ro = host ? new ResizeObserver(sync) : null;
    if (host && ro) ro.observe(host);
    window.addEventListener("resize", sync);
    return () => {
      ro?.disconnect();
      window.removeEventListener("resize", sync);
    };
  }, [hostRef, mode, paneId]);

  useEffect(() => {
    const host = hostRef.current;
    if (!host || mode === "never") return;

    const deactivate = () => {
      clearAutoFit(paneId);
      onActiveChange(false);
    };

    const onPointerDown = (e: PointerEvent) => {
      if (isInAutoCorner(host, paneId, e.clientX, e.clientY)) return;
      if (!isOnPriceOrTimeScale(host, paneId, e.clientX, e.clientY)) return;
      deactivate();
    };

    const onPointerUp = () => {
      if (!isAutoScaleOn(paneId) && active) onActiveChange(false);
    };

    const onWheel = (e: WheelEvent) => {
      if (isInAutoCorner(host, paneId, e.clientX, e.clientY)) return;
      if (!isOnPriceOrTimeScale(host, paneId, e.clientX, e.clientY)) return;
      deactivate();
    };

    host.addEventListener("pointerdown", onPointerDown);
    host.addEventListener("pointerup", onPointerUp);
    host.addEventListener("wheel", onWheel, { passive: true });
    return () => {
      host.removeEventListener("pointerdown", onPointerDown);
      host.removeEventListener("pointerup", onPointerUp);
      host.removeEventListener("wheel", onWheel);
    };
  }, [active, hostRef, mode, onActiveChange, paneId]);

  // Keep the auto button / engine aligned with the persisted preference.
  useEffect(() => {
    if (mode === "never") return;
    const sync = () => {
      const chartAuto = isAutoScaleOn(paneId);
      if (chartAuto === active) return;
      if (!chartAuto && active) {
        onActiveChange(false);
      } else if (chartAuto && !active) {
        clearAutoFit(paneId);
      }
    };
    sync();
    const host = hostRef.current;
    const ro = host ? new ResizeObserver(sync) : null;
    if (host && ro) ro.observe(host);
    return () => {
      ro?.disconnect();
    };
  }, [active, hostRef, mode, onActiveChange, paneId]);

  const chartBg = useAppStore((s) => s.chartSettings.backgroundColor) || "#000000";

  if (mode === "never") return null;

  const visibility =
    mode === "always"
      ? "opacity-100"
      : "opacity-0 pointer-events-none group-hover:opacity-100 group-hover:pointer-events-auto";

  const GEAR_W = 20;

  const containerStyle: CSSProperties = {
    position: "absolute",
    left: corner.left,
    top: corner.top,
    width: corner.width,
    height: corner.height,
    backgroundColor: chartBg,
    zIndex: 40,
  };

  const autoStyle: CSSProperties = {
    width: corner.width - GEAR_W,
    height: "100%",
  };

  const gearStyle: CSSProperties = {
    width: GEAR_W,
    height: "100%",
    position: "relative",
  };

  return (
    <div
      style={containerStyle}
      className={`flex items-center justify-between transition-opacity duration-100 ${visibility}`}
      onMouseDown={(e: ReactMouseEvent) => {
        e.preventDefault();
        e.stopPropagation();
      }}
    >
      {/* Auto label */}
      <button
        type="button"
        title={active ? "Auto on — click to turn off" : "Auto (fit visible prices)"}
        aria-label="Auto scale"
        aria-pressed={active}
        style={autoStyle}
        className={`flex items-center justify-center border-0 bg-transparent p-0 text-center text-[11px] leading-none transition-colors duration-100 ${
          active
            ? "font-bold text-white"
            : "font-medium text-(--app-muted) hover:text-(--app-text)"
        }`}
        onClick={(e) => {
          e.preventDefault();
          e.stopPropagation();
          setActivePane(paneId);
          if (active) {
            clearAutoFit(paneId);
            onActiveChange(false);
            return;
          }
          applyAutoFit(paneId);
          onActiveChange(true);
        }}
      >
        auto
      </button>

      {/* Gear / settings menu — to the right of the auto label */}
      <ChartScaleMenu
        paneId={paneId}
        style={gearStyle}
        visibility="opacity-100"
        autoScaleOn={active}
        onAutoChangeAction={onActiveChange}
      />
    </div>
  );
}
